  need: "必须先学完本站的《逻辑工具：如何评估一个论证》。那门课教的是「用逻辑做事」：把话拆成前提与结论、写真值表判定重言式、用自然演绎或推理规则写证明、看得懂「∀x(Fx → Gx)」这类量化写法、认得出常见谬误。本课默认这些动作你已经会做，并且不再重讲——它做的是退后一步的动作：把逻辑系统本身当作研究对象，问它有什么性质。数学门槛不高：你不需要学过高数、微积分或线性代数，本课用到的全部算术是「素数」「指数」「自然数」这一层，配手算例子；但你需要愿意接受一种二阶视角——前 1500 年人们用逻辑来研究别的东西，本课研究逻辑本身，因此对象与工具会同时出现在眼前，第 1 讲专门训练你不把两层搞混。如果《逻辑工具》还没学，请先去学它，否则本课的符号与术语会全部悬空。",
  blurb: "这门课要解决的问题是：一个证明系统凭什么算「好」。学完之后你能分清可靠性与完全性的两个方向、说清「一阶逻辑是完全的」与「算术是不完全的」为什么不矛盾、解释「完全但不判定」这个组合如何可能，并把市面上关于哥德尔定理的流行胡说逐条拆掉——最后还能对「逻辑只有一种吗」给出一个像样的立场与反驳。",
