            legend: "分层不是背口诀，而是每次动笔前问一句：我现在是在写公式，还是在写关于公式的话。对象语言（被讨论的那个语言）与元语言（用来讨论它的语言）的分界随「此刻把什么当作被讨论的语言」而移动，但一旦划定就不能混用。第 2 讲的可靠性与完全性、第 3 讲的不可判定性、第 4 讲的哥德尔定理全是后一种话，全都住在元语言里。"
