                  reply: "对。再补一层：⊢ 谈的是证明的存在，而证明是有穷符号对象，所以这条断言可以翻译成一句关于自然数的算术话（「存在一个数 y，它的结构符合证明的检查规则，且最后一行是 P → Q 的编码」）。第 3 讲与第 4 讲都要靠这个翻译。",
