          answer: 1,
          why: "B 对：这才是两个记号的默认读法，它们各自定义清楚，且不在一阶逻辑的符号表里。A 错：联结词只有 ¬ ∧ ∨ → ↔，⊢ 与 ⊨ 不构成公式的一部分。C 错：谈真不等于在对象语言里谈真——恰恰因为一阶逻辑的对象语言里没有「真」这个谓词，⊨ 才必须留在元语言。D 错：相继式演算确实可以把「Γ ⊢ φ」当作被操作的形式对象，那是把层次再抬一格的技术手段，但它不改变默认读法，也不能用来论证「⊢ 本来就属于对象语言」。"
