          passage: "本文讨论可计算数，也就是能被一台机器写出来的数。所谓机器，指的是这样一台装置：一条被分成方格的纸带，可以向两端无限延伸；一个读写头，能在纸带上读符号、写符号、并向左或向右移动一格；一个控制器，内部状态只有有穷多个。它的全部行为由一张有穷的规则表决定，每条规则说的是：处于某个状态、读到某个符号时，应当改写为什么符号、向哪边移动、转到哪个状态。这样一台装置在任何一步都不需要洞察力，它只看当前这一格与当前状态。本文证明存在一台通用机，它能模拟任何其他机器的行为，因此「可计算」这个概念不依赖于任何特定的机器。第 9 节讨论这套定义为什么可以作为「能行可计算」的准确刻画：一个人按照固定规则做机械计算时，实际用到的只有有穷多的事情——有穷多条规则、每一步只注意有穷多个符号、每次只看当前这一个位置。第 11 节把结果用到判定问题：不存在一台机器能判定任意给定的公式是否可证，因此希尔伯特与阿克曼提出的判定问题的答案是否定的。这里要小心一个区别：说不存在判定任意公式的机器，并不等于说每个公式都无法判定；对许多特殊的公式类，判定办法是存在的。",
