          passage: "本书要建立的是语言的逻辑句法，也就是对一个语言的形式规则作纯句法的研究：哪些符号串算句子、哪些句子可以从哪些句子推出来，这些问题都可以在不涉及符号意义的情况下讨论。在这种研究中，一个根本的态度是宽容原则（Principle of Tolerance）：我们不能预先规定哪一种语言形式是唯一正确的；逻辑里没有道德，人人都有自由按照自己的意愿构造自己的逻辑，也就是构造自己的语言形式。这种自由只有一个限制：构造出来的系统必须被明确写出，而且不能自相矛盾。因此，「哪一个系统是对的」这个问题，应当被替换为「哪一个系统对什么目的更方便」；前者是关于事实的理论问题，后者是关于选择的实践问题。要强调的是，宽容原则不是主张随便怎样都行：它要求每个系统都被明确写出它的形成规则与变形规则，并且要求我们在这个系统的内部讨论它的定理。",
